  textSecondary: '#b8b2a8',
  textTertiary: '#8e887e',
  textCaption: '#6f6a62',
  textDisabled: '#5a554e',
  accent: '#e86038',
  accentHover: '#f07049',
  accentPressed: '#d4512c',
  accentSoft: '#3a1f16',
  accentSofter: '#2a1710',
  onAccent: '#1a1917',
  success: '#8fbb4a',
  successSoft: '#2a3218',
  caution: '#e0a94a',
  cautionSoft: '#332a15',
  critical: '#ff8f7a',
  criticalSoft: '#3a1c17',
  focus: '#fff7f0',
  smoke: 'rgba(0, 0, 0, 0.55)',
  smokeStrong: 'rgba(0, 0, 0, 0.72)',
